"""Package a self-contained, beginner-friendly copy of the published guide."""
from pathlib import Path
import zipfile,html
ROOT=Path(__file__).resolve().parent.parent
DOCS=ROOT/'docs';OUT=DOCS/'Cipher-Getting-Started.zip'
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Start with Cipher</title><style>body{font:18px/1.6 system-ui,sans-serif;background:#f5faf5;color:#193323;max-width:1000px;margin:50px auto;padding:0 24px}h1{font-size:48px;letter-spacing:-2px;line-height:1.1}a{color:#216b3b}nav{display:flex;flex-wrap:wrap;gap:14px;margin:28px 0}nav a{background:#e1f0e4;padding:14px 18px;border-radius:12px;text-decoration:none;font-weight:650}video{width:100%;border-radius:16px;background:#102015}small{color:#526c5b}section{padding:20px 0;border-top:1px solid #d7e5da}</style><h1>Start with Cipher.</h1><p>A guide from downloading the app to your first saved file. You do not need coding knowledge for the first exercise.</p><nav><a href="Cipher-Beginners-Handbook.pdf">Read the picture handbook</a><a href="Cipher-Quickstart.mp4">Open the narrated video</a><a href="TRANSCRIPT.html">Read the video transcript</a></nav><video controls preload="metadata" poster="media/cipher-video-poster.png"><source src="Cipher-Quickstart.mp4" type="video/mp4"><track kind="captions" src="media/cipher-walkthrough.vtt" srclang="en" label="English" default></video><p><small>Captions are also printed into the video. First-install views and prepared teaching edits are labelled illustrations. The sample file save and test result are real. No model download is demonstrated.</small></p><section><h2>Choose your starting point</h2><p><strong>Already have Ollama?</strong> Keep it installed. Open Models &amp; downloads and choose your installed model.</p><p><strong>Starting fresh?</strong> Install the internal local engine first. Start it, download a model, then choose Use this model.</p><p><strong>Cloud API?</strong> Enter your provider details in Settings. Local Ollama is not needed for a cloud API.</p></section><section><h2>Your first task</h2><p>Receive a simple reply, open a new practice folder, and ask Cipher to create hello.txt. Review the proposed text, approve the save, and open the file to check it. The handbook gives each step.</p><p><a href="tutorial-project.zip">Optional coding practice project</a> - extract this separately if you want the Python exercise. It has an intentional bug. Python is not needed for the first hello.txt task.</p></section><section><h2>Get the app</h2><p><a href="https://github.com/theprology/cipher/releases/latest">Download the latest Cipher</a> - the handbook explains which installer to choose.</p><p>Initial engine/model downloads, search, browsing and cloud APIs require internet. This guide and video can be read locally after you extract the bundle.</p></section></html>'''
transcript=(DOCS/'media/TRANSCRIPT.md').read_text().splitlines();parts=[]
for line in transcript:
 if line.startswith('# '):parts.append('<h1>'+html.escape(line[2:])+'</h1>')
 elif line.startswith('## '):parts.append('<h2>'+html.escape(line[3:])+'</h2>')
 elif line.strip():parts.append('<p>'+html.escape(line.strip('*'))+'</p>')
transcript_html='<!doctype html><meta charset="utf-8"><title>Cipher video transcript</title><style>body{font:18px/1.6 system-ui,sans-serif;max-width:850px;margin:40px auto;padding:0 20px;color:#193323}h2{margin-top:40px}</style><a href="START-HERE.html">Back to start</a>'+''.join(parts)
with zipfile.ZipFile(OUT,'w',zipfile.ZIP_DEFLATED) as z:
 z.writestr('START-HERE.html',page);z.writestr('TRANSCRIPT.html',transcript_html)
 for p,name in [(DOCS/'Cipher-Beginners-Handbook.pdf','Cipher-Beginners-Handbook.pdf'),(DOCS/'media/cipher-walkthrough.mp4','Cipher-Quickstart.mp4'),(DOCS/'WALKTHROUGH.md','WALKTHROUGH.md'),(DOCS/'MODEL_LIBRARY.md','MODEL_LIBRARY.md'),(DOCS/'COMPUTER_USE.md','COMPUTER_USE.md'),(DOCS/'tutorial-project.zip','tutorial-project.zip'),(ROOT/'LICENSE','LICENSE')]:z.write(p,name)
 for p in sorted((DOCS/'media').iterdir()):
  if p.is_file() and p.suffix in ['.png','.gif','.md','.srt','.vtt']:z.write(p,'media/'+p.name)
print(OUT,OUT.stat().st_size)
